def converter_status(apps, schema_editor):
    """Converte os status antigos para os novos estados do pedido."""
    Pedido = apps.get_model("pedidos", "pedido")
    for antigo, novo in MAPA_STATUS.items():
        Pedido.objects.filter(status=antigo).update(status=novo)


def preencher_uuids(apps, schema_editor):
    """Gera um UUID diferente para cada linha já existente."""
    for modelo, campo in (("pedido", "codigo"), ("pagamento", "referencia")):
        Modelo = apps.get_model("pedidos", modelo)
        for obj in Modelo.objects.filter(**{f"{campo}__isnull": True}):
            setattr(obj, campo, uuid.uuid4())
            obj.save(update_fields=[campo])


